package com.alpharip.staffmod.BuildTimelapse.export;
import java.io.*;import java.nio.file.*;import java.util.*;
/** External FFmpeg adapter; FFmpeg must be installed separately. */
public final class FfmpegVideoEncoder implements VideoEncoder {
 private final String exe;public FfmpegVideoEncoder(String e){exe=e==null||e.trim().isEmpty()?"ffmpeg":e.trim();}
 public void encode(ExportJob j)throws Exception{if(j==null)throw new IllegalArgumentException("job");File frames=j.getFrames();if(!frames.isDirectory())throw new FileNotFoundException(frames.toString());ExportSettings s=j.getSettings();File output=j.getOutput();if(s.getFormat()==ExportSettings.Format.IMAGE_SEQUENCE){copySequence(frames,output);return;}if(s.getFormat()==ExportSettings.Format.MP4&&((s.getWidth()&1)!=0||(s.getHeight()&1)!=0))throw new IllegalArgumentException("MP4 dimensions must be even for yuv420p output");File parent=output.getAbsoluteFile().getParentFile();if(parent!=null&&!parent.exists()&&!parent.mkdirs())throw new IOException("Cannot create export directory: "+parent);List<String> c=new ArrayList<String>();Collections.addAll(c,exe,"-y","-framerate",Integer.toString(s.getFps()),"-i",new File(frames,"frame-%08d.png").getAbsolutePath());if(s.getFormat()==ExportSettings.Format.MP4)Collections.addAll(c,"-vf","scale="+s.getWidth()+":"+s.getHeight()+":force_original_aspect_ratio=decrease,pad="+s.getWidth()+":"+s.getHeight()+":(ow-iw)/2:(oh-ih)/2","-an","-c:v","libx264","-pix_fmt","yuv420p",output.getAbsolutePath());else if(s.getFormat()==ExportSettings.Format.GIF)Collections.addAll(c,"-vf","fps="+s.getFps()+",scale="+s.getWidth()+":"+s.getHeight()+":flags=lanczos",output.getAbsolutePath());else throw new UnsupportedOperationException("Unsupported export format");Process p=new ProcessBuilder(c).redirectErrorStream(true).start();StringBuilder log=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream(),"UTF-8"))){String line;while((line=r.readLine())!=null){if(log.length()>12000)log.delete(0,6000);log.append(line).append('\n');}}int exit=p.waitFor();if(exit!=0)throw new IOException("FFmpeg failed with exit code "+exit+": "+log);if(!output.isFile()||output.length()==0)throw new IOException("FFmpeg did not create a valid output file");}
 private void copySequence(File source,File destination)throws IOException{if(!destination.exists()&&!destination.mkdirs())throw new IOException("Cannot create image sequence output directory");if(!destination.isDirectory())throw new IOException("Image sequence output is not a directory");File[] png=source.listFiles(new FilenameFilter(){public boolean accept(File d,String n){return n.matches("frame-[0-9]{8}\\.png");}});if(png==null||png.length==0)throw new IOException("No captured PNG frames found");Arrays.sort(png,new Comparator<File>(){public int compare(File a,File b){return a.getName().compareTo(b.getName());}});for(File f:png){File target=new File(destination,f.getName());if(!f.getCanonicalFile().equals(target.getCanonicalFile()))Files.copy(f.toPath(),target.toPath(),StandardCopyOption.REPLACE_EXISTING);}}
}